INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I027', 'name_conflict', '{"type":"name_conflict","source_statement":"10-4の実践2見出しが「食前の休息呼吸」だが、手順は食後、第10章一覧も食後","editorial_action":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。","proposed_wording":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P105','P106']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I028', 'duplicate_layout', '{"type":"duplicate_layout","source_statement":"第13章に13-4の図版が2種類ある","editorial_action":"13-4の2図版は両方を保存する。正式掲載に使う1点を選び、もう1点は旧案として区別する。","proposed_wording":"13-4の2図版は両方を保存する。正式掲載に使う1点を選び、もう1点は旧案として区別する。","remaining_work":"章番号・掲載画像の具体的な選択は未確定"}', 'editorial_policy_applied', ARRAY['P112','P113']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I029', 'timing_variants', '{"type":"timing_variants","source_statement":"第14章は同名の基本技法と秒数・吐き方が異なる","editorial_action":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。","proposed_wording":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P107','P108','P117','P118']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I030', 'scientific_review', '{"type":"scientific_review","source_statement":"空気の経路に副鼻腔・血液・細胞を直列表示","editorial_action":"空気の通路と、肺胞から血液・細胞への酸素の運搬を2段に分けて図示する。副鼻腔を必須の直列通過点にしない。","proposed_wording":"空気の通路と、肺胞から血液・細胞への酸素の運搬を2段に分けて図示する。副鼻腔を必須の直列通過点にしない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P149']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I031', 'internal_inconsistency', '{"type":"internal_inconsistency","source_statement":"一回の呼吸は約0.5秒／図の0.9秒","editorial_action":"一呼吸の周期と肺まで空気が移動する時間を区別する。「約0.5秒」「0.9秒」は定義・根拠確認まで掲載しない。","proposed_wording":"一呼吸の周期と肺まで空気が移動する時間を区別する。「約0.5秒」「0.9秒」は定義・根拠確認まで掲載しない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P151']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I032', 'scientific_review', '{"type":"scientific_review","source_statement":"肺には筋肉がありません／肺は動かない","editorial_action":"肺は、自分で筋肉を縮めて空気を吸い込む器官ではありません。横隔膜や肋骨の間の筋肉が働いて胸の中の空間を広げると、それに伴って肺が膨らみ、空気が入ります。","proposed_wording":"肺は、自分で筋肉を縮めて空気を吸い込む器官ではありません。横隔膜や肋骨の間の筋肉が働いて胸の中の空間を広げると、それに伴って肺が膨らみ、空気が入ります。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P152']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I033', 'scientific_review', '{"type":"scientific_review","source_statement":"肋骨運動の名称と方向、全肋骨が胸骨につながる図","editorial_action":"肋骨の動きの名称・方向・胸骨との接続先を監修し、図と本文を同時に修正する。","proposed_wording":"肋骨の動きの名称・方向・胸骨との接続先を監修し、図と本文を同時に修正する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P153']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I034', 'scientific_review', '{"type":"scientific_review","source_statement":"呼気時の胸腔内圧を一律に陽圧として表す","editorial_action":"図に圧の測定部位・基準・単位・呼吸条件を明記する。確認前は「呼気時の胸腔内圧は陽圧」という一律の説明を外す。","proposed_wording":"図に圧の測定部位・基準・単位・呼吸条件を明記する。確認前は「呼気時の胸腔内圧は陽圧」という一律の説明を外す。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P154','P155']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I035', 'internal_inconsistency', '{"type":"internal_inconsistency","source_statement":"SpO₂の章内の区分不一致","editorial_action":"章内のSpO₂区分表は回答用から外し、統一する医学的な基準・対象・条件を監修者に確認する。","proposed_wording":"章内のSpO₂区分表は回答用から外し、統一する医学的な基準・対象・条件を監修者に確認する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P158']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I036', 'scientific_review', '{"type":"scientific_review","source_statement":"酸素タクシーは満員で出発、細胞で全席空く","editorial_action":"酸素タクシーは、結合部位を学ぶためのたとえです。必ず満席で出発し、全部を降ろすという意味ではありません。","proposed_wording":"酸素タクシーは、結合部位を学ぶためのたとえです。必ず満席で出発し、全部を降ろすという意味ではありません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P163']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I037', 'internal_inconsistency', '{"type":"internal_inconsistency","source_statement":"肺胞数3〜5億と2億5000万の違い","editorial_action":"肺胞数は出典と条件が確認できた数値のみを記載する。確認前は「多数の肺胞」という説明にとどめる。","proposed_wording":"肺胞数は出典と条件が確認できた数値のみを記載する。確認前は「多数の肺胞」という説明にとどめる。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P156','P164']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I038', 'internal_arithmetic', '{"type":"internal_arithmetic","source_statement":"37兆個の細胞と37兆個のミトコンドリアの混同","editorial_action":"細胞数とミトコンドリア数は分けて記載する。計算例として37兆×1.5µmを使うなら55,500km。ただし実際の総数・長さの説明としては未確定。","proposed_wording":"細胞数とミトコンドリア数は分けて記載する。計算例として37兆×1.5µmを使うなら55,500km。ただし実際の総数・長さの説明としては未確定。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P168','P170']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I039', 'scientific_review', '{"type":"scientific_review","source_statement":"運動・呼吸・食品・栄養補助成分でミトコンドリアが増えるという一覧","editorial_action":"運動・睡眠・食事などの生活要素を紹介する。個別成分でミトコンドリアが増える、若返るという断定や摂取指示は掲載しない。","proposed_wording":"運動・睡眠・食事などの生活要素を紹介する。個別成分でミトコンドリアが増える、若返るという断定や摂取指示は掲載しない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P171']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I040', 'scientific_review', '{"type":"scientific_review","source_statement":"疲労等のすべての原因はATP不足・低酸素","editorial_action":"この図だけで、本人の疲労や眠気の原因をATP不足・低酸素と判断することはできません。","proposed_wording":"この図だけで、本人の疲労や眠気の原因をATP不足・低酸素と判断することはできません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P159','P172','P211']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I041', 'scientific_review', '{"type":"scientific_review","source_statement":"吸気＝交感、呼気＝副交感の二値スイッチ／唯一・最も確実","editorial_action":"呼吸と自律神経の関係を学びます。吸気・呼気を全身の神経状態が完全に切り替わるスイッチとして説明しません。","proposed_wording":"呼吸と自律神経の関係を学びます。吸気・呼気を全身の神経状態が完全に切り替わるスイッチとして説明しません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P180','P184','P185']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I042', 'scientific_review', '{"type":"scientific_review","source_statement":"グラフの「心拍（R-R間隔）」","editorial_action":"「心拍数」と「R-R間隔」を別の量として表示する。軸名・単位・波形の向きを確認して図を差し替える。","proposed_wording":"「心拍数」と「R-R間隔」を別の量として表示する。軸名・単位・波形の向きを確認して図を差し替える。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P185']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I043', 'citation_review', '{"type":"citation_review","source_statement":"Frontiers・NCBI・PMC・med.navy.mil等だけの引用","editorial_action":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。","proposed_wording":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。","remaining_work":"引用元の特定・照合が必要"}', 'editorial_policy_applied', ARRAY['P174','P183','P184','P187','P207']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I044', 'internal_inconsistency', '{"type":"internal_inconsistency","source_statement":"導入4-4-6〜8-4秒とボックス4-4-4-4秒の差","editorial_action":"等時間のボックス呼吸と導入図の不等時間例を別表示する。導入例の名称が決まるまで実践配信は保留する。","proposed_wording":"等時間のボックス呼吸と導入図の不等時間例を別表示する。導入例の名称が決まるまで実践配信は保留する。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P186','P187','P188']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I045', 'label_correction', '{"type":"label_correction","source_statement":"呼吸カウントの図3人目が吐いて1、本文は吸って2","editorial_action":"図の順序案：吸って1 → 吐いて1 → 吸って2 → 吐いて2。3人目のラベルを本文に合わせる。","proposed_wording":"図の順序案：吸って1 → 吐いて1 → 吸って2 → 吐いて2。3人目のラベルを本文に合わせる。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P197']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I046', 'classification_update', '{"type":"classification_update","source_statement":"NREM睡眠をステージ1〜4で記載","editorial_action":"NREM睡眠をN1・N2・N3の3段階に整理する。図の配置と本文をまとめて更新する。","proposed_wording":"NREM睡眠をN1・N2・N3の3段階に整理する。図の配置と本文をまとめて更新する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P206']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I047', 'scientific_review', '{"type":"scientific_review","source_statement":"NOから脳・免疫・いびき・睡眠への効果をつなぐ図","editorial_action":"鼻の構造・NOの説明と、脳・免疫・いびき・睡眠への効果の主張を別に扱う。効能の矢印は根拠確認まで保留する。","proposed_wording":"鼻の構造・NOの説明と、脳・免疫・いびき・睡眠への効果の主張を別に扱う。効能の矢印は根拠確認まで保留する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P196','P208']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I048', 'scientific_review', '{"type":"scientific_review","source_statement":"深呼吸で代謝・血流・老廃物排出・消化排泄が一律に改善","editorial_action":"呼吸と日常のコンディショニングの関係を学びます。「誰でも一律に代謝・血流・排出・消化が改善する」という保証は削る。","proposed_wording":"呼吸と日常のコンディショニングの関係を学びます。「誰でも一律に代謝・血流・排出・消化が改善する」という保証は削る。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P213','P215','P216']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I049', 'scientific_review', '{"type":"scientific_review","source_statement":"声の質のすべてが呼吸で決まる／胸・頭を共鳴腔として図示","editorial_action":"声は、呼吸・声帯・共鳴・発音などが関係して生まれます。胸や頭に感じる響きと、解剖学的な共鳴腔は区別して監修する。","proposed_wording":"声は、呼吸・声帯・共鳴・発音などが関係して生まれます。胸や頭に感じる響きと、解剖学的な共鳴腔は区別して監修する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P223']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I050', 'editorial_metadata', '{"type":"editorial_metadata","source_statement":"外部監修を入れる場合の配置候補","editorial_action":"「監修候補・未依頼」という制作メモとして保存する。教材本文やAIの回答に監修済みと表示しない。","proposed_wording":"「監修候補・未依頼」という制作メモとして保存する。教材本文やAIの回答に監修済みと表示しない。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P224']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I051', 'terminology_review', '{"type":"terminology_review","source_statement":"アシュタンガの八支則と流派名の関係","editorial_action":"八支則を意味する用語としてのアシュタンガと、現代の実践スタイルの名称を分け、歴史・用語の監修後に確定する。","proposed_wording":"八支則を意味する用語としてのアシュタンガと、現代の実践スタイルの名称を分け、歴史・用語の監修後に確定する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P231']::text[]) ON CONFLICT (issue_id) DO NOTHING;